-- Booking Service database. flight_id references a flight in Flight Service's own database,
-- so it is a logical reference without a FK (no shared databases between services).

CREATE TYPE booking_status AS ENUM ('CONFIRMED', 'CANCELLED');

CREATE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TABLE bookings (
    -- generated by Booking Service before ReserveSeats: also the idempotency key of the reservation
    id              UUID PRIMARY KEY,
    user_id         VARCHAR(64)    NOT NULL CHECK (char_length(user_id) >= 1),
    flight_id       UUID           NOT NULL,
    passenger_name  VARCHAR(200)   NOT NULL CHECK (char_length(passenger_name) >= 1),
    passenger_email VARCHAR(255)   NOT NULL,
    seat_count      INTEGER        NOT NULL CHECK (seat_count > 0),
    -- price snapshot: seat_count * flight price at booking time
    total_price     NUMERIC(12, 2) NOT NULL CHECK (total_price > 0),
    status          booking_status NOT NULL DEFAULT 'CONFIRMED',
    created_at      TIMESTAMPTZ    NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ    NOT NULL DEFAULT now()
);
CREATE INDEX idx_bookings_user_id ON bookings (user_id, created_at DESC);
CREATE INDEX idx_bookings_flight_id ON bookings (flight_id);
CREATE TRIGGER trg_bookings_updated_at BEFORE UPDATE ON bookings
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
